1	import React from 'react';
2	import { Flex, Text } from '@chakra-ui/react';
3	import { ZimmIcon } from '../zimmIcon';
4	
5	type ZimmSelectedChipProps = {
6	  label: string;
7	  onRemove: () => void;
8	  /** Visual style — 'filled' (default): dark background, inverse label, for the filter drawer.
9	   *  'outlined': transparent background with a dark label, for the page-level applied filter
10	   *  bar. Borderless by design: the chips sit in a labelled row, so the row itself provides
11	   *  the grouping and an outline would add visual weight the design does not call for. */
12	  variant?: 'filled' | 'outlined';
13	};
14	
15	/**
16	 * Interim chip used for selected refinements in the SFCC-847 filter drawer and page-level
17	 * applied filter bar. Two variants:
18	 * - `filled` (default): black background, white label — used inside the drawer.
19	 * - `outlined`: transparent background, dark label, no border — used in the page bar.
20	 * SFCC-108 replaces this with the final Zimmermann-branded Selected chip design and this atom is retired.
21	 *
22	 * @param props see ZimmSelectedChipProps
23	 */
24	export const ZimmSelectedChip = ({ label, onRemove, variant = 'filled' }: ZimmSelectedChipProps) => {
25	  const filled = variant === 'filled';
26	  return (
27	    <Flex
28	      as="button"
29	      type="button"
30	      display="inline-flex"
31	      alignItems="center"
32	      justifyContent="center"
33	      gap="var(--zimm-scale-2xs)"
34	      paddingInline="var(--zimm-scale-l)"
35	      // audit-allow: Figma chip height (node 40003890:151757) with no equivalent --zimm-*
36	      // token; the spacing scale has no 40px step and actionSizes tops out at 52/40 for
37	      // buttons, which is a different component. Revisit if SFCC-108 introduces a chip token.
38	      height="40px"
39	      backgroundColor={filled ? 'var(--zimm-color-text-default)' : 'transparent'}
40	      color={filled ? 'var(--zimm-color-text-inverse)' : 'var(--zimm-color-text-default)'}
41	      border="none"
42	      cursor="pointer"
43	      flexShrink={0}
44	      onClick={onRemove}
45	      aria-label={`Remove filter: ${label}`}
46	      _hover={{
47	        backgroundColor: filled ? 'var(--zimm-color-text-secondary)' : 'var(--zimm-color-bg-02)',
48	      }}
49	    >
50	      <Text as="span" textStyle={filled ? 'buttonSm' : 'productNames'}>
51	        {label}
52	      </Text>
53	      {/* Decorative — the chip's own aria-label above already announces "Remove filter: ...". */}
54	      <ZimmIcon type="close" size="sm" aria-hidden={true} />
55	    </Flex>
56	  );
57	};
