1	import { describe, test, expect } from 'vitest';
2	import { renderHook, act } from '@testing-library/react';
3	import { useFilterDrawerState, buildAppliedRefine } from './useFilterDrawerState';
4	
5	describe('useFilterDrawerState', () => {
6	  test('resyncs pending state from currently-applied filters when the drawer opens', () => {
7	    const { result, rerender } = renderHook(
8	      ({ isOpen }) =>
9	        useFilterDrawerState({
10	          isOpen,
11	          categoryId: 'clothing',
12	          selectedRefinements: { c_size: 'S|M', cgid: 'clothing' },
13	        }),
14	      { initialProps: { isOpen: false } },
15	    );
16	
17	    expect(result.current.pendingRefine).toEqual({});
18	
19	    rerender({ isOpen: true });
