function cachedConsumers({category, rel, stem, content, incremental, isTouchedRow, nextCache}) {
  const cached = overrideCache[category][rel]
  if (incremental && !isTouchedRow) {
    const consumers = cached ? cached.consumers : '—'
    nextCache[rel] = {...nextCache[rel], ...cached, consumers}
    return consumers
  }
  const hash = hashContent(content)
  const consumers = cached && cached.hash === hash ? cached.consumers : countConsumers(stem)
  nextCache[rel] = {...nextCache[rel], hash, consumers}
  return consumers
}

