function cachedLastTouched({category, rel, incremental, isTouchedRow, nextCache}) {
  const cached = overrideCache[category][rel]
  if (incremental && !isTouchedRow) {
    const lastTouched = cached?.lastTouched ?? '—'
    nextCache[rel] = {...nextCache[rel], ...cached, lastTouched}
    return lastTouched
  }
  const lastTouched = getLastTouched(rel)
  nextCache[rel] = {...nextCache[rel], lastTouched}
  return lastTouched
}

function countConsumers(stem) {
  try {
    const count = execSync(
      `grep -rl "${stem}" "${APP}" --include="*.js" --include="*.jsx" --include="*.ts" --include="*.tsx" 2>/dev/null | grep -v "\\.test\\." | grep -v "${stem}\\." | wc -l`,
      {encoding: 'utf-8', timeout: 8000}
    )
    return parseInt(count.trim(), 10) || 0
  } catch {
    return '—'
  }
}

